"use strict";exports.filterCities=function(t,e){return t.filter(t=>("all"===e.region||t.region===e.region)&&!(e.types.length>0&&!e.types.some(e=>t.types.includes(e))))},exports.randomSelect=function(t){return t[Math.floor(Math.random()*t.length)]},exports.sampleCities=function(t,e){const n=[...t];for(let r=n.length-1;r>0&&r>=n.length-e;r--){const t=Math.floor(Math.random()*(r+1));[n[r],n[t]]=[n[t],n[r]]}return n.slice(-e)};
